24	// TestExpandProseResolutionPromotesPassagesIntoSpareSlots is the whole point of the pass: the
25	// finer regions the ranker already computed become results a consumer that reads `results[]`
26	// can see, instead of staying in a field it never asked about.
27	func TestExpandProseResolutionPromotesPassagesIntoSpareSlots(t *testing.T) {
28		t.Parallel()
29		results := []SearchResult{
30			proseResolutionParent(1, "sessions/one.md", 10, "primary one",
31				proseResolutionPassage(30, "one alpha"), proseResolutionPassage(50, "one beta")),
32		}
33	
34		expanded := expandProseResolution(results, 10, 0)
35	
36		if len(expanded) != 3 {
37			t.Fatalf("expanded to %d results, want 3", len(expanded))
38		}
39		if len(expanded[0].Passages) != 0 {
40			t.Fatalf("promoted passages still attached to the parent: %#v", expanded[0].Passages)
41		}
42		for index, want := range []struct {
43			line    int
44			snippet string
45		}{{30, "one alpha"}, {50, "one beta"}} {
