47			if got.Rank != index+2 {
48				t.Fatalf("rank %d at index %d", got.Rank, index+1)
49			}
50			if got.FilePath != "sessions/one.md" || got.StartLine != want.line || got.EndLine != want.line ||
51				got.SnippetStartLine != want.line || got.SnippetEndLine != want.line || got.FocusLine != want.line {
52				t.Fatalf("promoted span = %#v, want lines %d", got, want.line)
53			}
54			if got.Snippet != want.snippet {
55				t.Fatalf("promoted snippet = %q, want %q", got.Snippet, want.snippet)
56			}
57			if got.Score != results[0].Score {
58				t.Fatalf("promoted score = %v, want the parent's %v", got.Score, results[0].Score)
59			}
60			if !hasSearchSignal(got, proseResolutionSignal) {
61				t.Fatalf("promoted result is not labelled: %#v", got.Signals)
62			}
63			if got.SymbolID != "" || got.SymbolName != "" || got.QualifiedName != "" {
64				t.Fatalf("promoted result claims the parent's symbol identity: %#v", got)
65			}
66		}
67		if len(results[0].Passages) != 2 {
68			t.Fatalf("input was mutated: %#v", results[0].Passages)
69		}
