72	// TestExpandProseResolutionNeverDisplacesAFile is the property that separates this from --deep:
73	// the expansion only ever fills slots the distinct-file ranking left empty.
74	func TestExpandProseResolutionNeverDisplacesAFile(t *testing.T) {
75		t.Parallel()
