92	// TestExpandProseResolutionRoundRobinsAcrossParents stops one long document spending every spare
93	// slot before a second document has contributed anything.
94	func TestExpandProseResolutionRoundRobinsAcrossParents(t *testing.T) {
95		t.Parallel()
96		results := []SearchResult{
97			proseResolutionParent(1, "sessions/one.md", 10, "primary one",
98				proseResolutionPassage(30, "one alpha"), proseResolutionPassage(50, "one beta")),
99			proseResolutionParent(2, "sessions/two.md", 20, "primary two",
