101		}
102	
103		expanded := expandProseResolution(results, 4, 0)
104	
105		if len(expanded) != 4 {
106			t.Fatalf("expanded to %d results, want 4", len(expanded))
107		}
108		// Round robin is a property of WHICH passages are promoted, not of where they are printed:
109		// the second document contributes before the first document contributes twice. `one beta` is
110		// the first document's depth-2 passage, so its absence is the property under test. (Position
111		// is no longer meaningful here — results[] is re-sorted by score, so a promotion is reported
112		// beside its parent rather than at the end.)
113		promoted := map[string]bool{}
114		bySnippet := map[string]SearchResult{}
115		for _, result := range expanded {
116			bySnippet[result.Snippet] = result
117			if hasSearchSignal(result, proseResolutionSignal) {
