132	// TestExpandProseResolutionKeepsResultsScoreOrdered pins the invariant results[] advertises.
133	// Promotions inherit their parent's score, so appending them left a high-scoring passage sitting
134	// behind every low-scoring parent: a consumer taking "top 20 by score" got a different set than
135	// the first 20 entries, which is precisely the consumer this pass exists to serve.
136	func TestExpandProseResolutionKeepsResultsScoreOrdered(t *testing.T) {
