192	// TestExpandProseResolutionIgnoresResultsWithoutPassages is the code-search case: nothing to
193	// promote, so nothing changes.
194	func TestExpandProseResolutionIgnoresResultsWithoutPassages(t *testing.T) {
195		t.Parallel()
196		results := []SearchResult{
197			{Rank: 1, FilePath: "internal/sem/search.go", StartLine: 1, EndLine: 2, FocusLine: 1,
