208	// TestSearchRepositoryReturnsMultiResolutionProseResults exercises the wiring end to end, and its
209	// --single-resolution counterpart proves the switch restores the previous shape.
210	func TestSearchRepositoryReturnsMultiResolutionProseResults(t *testing.T) {
