226				t.Context(), repo, "test", "amber lantern orchard ledger", SearchOptions{
227					Worktree:           true,
228					Profile:            ProfileSyntaxOnly,
229					TopK:               40,
230					MaxIndexedFiles:    32,
231					MaxContextBytes:    400000,
